local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local payload = ""
local key = 83
local values = {}
local buffer = 0
local bits = 0

for i = 1, #payload do
    local char = payload:sub(i, i)
    if char ~= "=" then
        local value = alphabet:find(char, 1, true) - 1
        buffer = buffer * 64 + value
        bits = bits + 6

        if bits >= 8 then
            bits = bits - 8
            local byte = math.floor(buffer / (2 ^ bits)) % 256
            buffer = buffer % (2 ^ bits)
            values[#values + 1] = string.char((byte - ((key + (#values + 1) * 17) % 251)) % 256)
        end
    end
end

local source = table.concat(values)
local execute = loadstring or load
if not execute then
    error("SWS HUB requires loadstring support in this executor")
end

local chunk, reason = execute(source)
if not chunk then
    error(reason)
end

chunk()
